@cached_property
def _execution_order(self) -> tuple[str, ...]:
    """Topologically sorted node names.

    Computed once at construction, cached for efficiency.
    """
    return self._topological_sort()

def _topological_sort(self) -> tuple[str, ...]:
    """Kahn's algorithm for topological sorting."""
    # Build adjacency and in-degree maps
    in_degree = {name: 0 for name in self.nodes}
    adjacency = {name: [] for name in self.nodes}

    for wire in self.wires:
        adjacency[wire.source_node].append(wire.target_node)
        in_degree[wire.target_node] += 1

    # Start with nodes that have no incoming edges
    queue = [name for name, deg in in_degree.items() if deg == 0]
    result = []

    while queue:
        node = queue.pop(0)
        result.append(node)
        for neighbor in adjacency[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) != len(self.nodes):
        raise ValueError("Graph contains a cycle")

    return tuple(result)

