def make_simple_feedback(
    network: Network,
    mechanics: Mechanics,
    feedback_delay: int = 5,
    feedback_noise: float = 0.01,
) -> Graph:
    """Construct a SimpleFeedback model as an explicit graph."""

    feedback = FeedbackChannel(
        delay=feedback_delay,
        noise_std=feedback_noise,
        init_shape=(2,),  # 2D effector position
    )

    return Graph(
        nodes={
            "feedback": feedback,
            "network": network,
            "mechanics": mechanics,
        },
        wires=(
            Wire("feedback", "output", "network", "feedback"),
            Wire("network", "output", "mechanics", "force"),
            # Note: mechanics.effector -> feedback.input happens via state
            # The feedback channel reads previous effector from state
        ),
        input_ports=("target", "effector_state"),
        output_ports=("effector",),
        input_bindings={
            "target": ("network", "target"),
            "effector_state": ("feedback", "input"),  # Current effector for feedback queue
        },
        output_bindings={
            "effector": ("mechanics", "effector"),
        },
    )

